{{!-- Styling parameters: class, titleClass, descriptionClass, imageClass --}}
{{#with this as |ghostcnStyles|}}
<header class="ghcn-archive-header{{#if ghostcnStyles.class}} {{ghostcnStyles.class}}{{/if}}">
  {{#if eyebrow}}{{> "components/badge" text=eyebrow variant="secondary" class=ghostcnStyles.badgeClass}}{{/if}}
  <h1 class="ghcn-archive-header__title{{#if ghostcnStyles.titleClass}} {{ghostcnStyles.titleClass}}{{/if}}">{{#if heading}}{{heading}}{{else}}{{#if name}}{{name}}{{else}}{{@site.title}}{{/if}}{{/if}}</h1>
  {{#if description}}<p class="ghcn-archive-header__description{{#if ghostcnStyles.descriptionClass}} {{ghostcnStyles.descriptionClass}}{{/if}}">{{description}}</p>{{else}}{{#if bio}}<p class="ghcn-archive-header__description{{#if ghostcnStyles.descriptionClass}} {{ghostcnStyles.descriptionClass}}{{/if}}">{{bio}}</p>{{/if}}{{/if}}
  {{#if archiveImage}}<img class="ghcn-archive-header__image{{#if ghostcnStyles.imageClass}} {{ghostcnStyles.imageClass}}{{/if}}" src="{{img_url archiveImage size="l"}}" alt="{{imageAlt}}" />{{/if}}
</header>
{{/with}}

.ghcn-archive-header { font-size: 16px; color: var(--foreground); text-align: center; margin-block: 2em; }
.ghcn-archive-header__title { font-size: clamp(2em,5vw,3em); line-height: 1.1; margin: .5em 0; overflow-wrap: anywhere; }
.ghcn-archive-header__description { max-width: 42em; margin: 1em auto; color: var(--muted-foreground); }
.ghcn-archive-header__image { display: block; width: 100%; max-height: 28em; object-fit: cover; border-radius: var(--radius); margin-top: 2em; }
